INSERT  IGNORE INTO `reviews` VALUES (1,103,5,'Akhilan','Flux Coliving','Stayed here for almost 6 months and honestly had a good experience. Rooms are clean and housekeeping is regular. Food is much better compared to other PGs I’ve seen in Bangalore. Staff is also helpful whenever there’s any issue.','2026-03-24 12:06:33'),(2,104,5,'Harini','Orion Coliving','I shifted here after a bad PG experience, and this place felt much better. It’s calm, not too crowded, and you actually get some personal space. WiFi is stable enough for work, which was very important for me.','2026-03-24 12:10:26'),(3,105,5,'Rahul ','Flokq coliving','For the price, this PG is totally worth it. You get decent food, clean rooms, and basic facilities without much hassle. Not luxury, but definitely comfortable for daily living.','2026-03-24 12:10:55'),(4,69,5,'Arjun','Classic Gold House',NULL,'2026-03-24 12:11:14'),(5,73,5,'Sneha','Lavender House','The environment here is nice. People are friendly and you don’t feel isolated. It’s easy to interact with others, especially if you’re new to the city.','2026-03-24 12:12:31');
